export function poolCountsOk(p, s, bo, prec) {
    const g = p[prec + 1];
    const pso = p[prec + 4];
    if (g < 0) {
        return true;
    }
    const go = groupRec(p, g);
    const ne = p[go];
    for (let j = 0; j < ne; j++) {
        if (s[((bo + pso) + 4) + j] < p[((go + 2) + (4 * j)) + 2]) {
            return false;
        }
    }
    return true;
}

export function factorSat(p, s, bo, mt, f) {
    // Has factor f a live alternative with every required literal consumed,
    // whose pool has every group entry at or above its minimum?
    const pools = mPools(p, mt);
    const alts = mAlts(p, mt);
    const frec = (mt + 8) + (4 * f);
    const pf = p[frec + 2];
    const pc = p[frec + 3];
    for (let k = 0; k < pc; k++) {
        const prec = pools + (5 * (pf + k));
        if (poolCountsOk(p, s, bo, prec)) {
            const af = p[prec + 2];
            const ac = p[prec + 3];
            for (let ai = 0; ai < ac; ai++) {
                const a = af + ai;
                const arec = alts + (5 * a);
                const aso = p[arec + 4];
                if (altLive(p, s, bo, pools, alts, a)) {
                    if (s[(bo + aso) + 2] === p[arec + 3]) {
                        return true;
                    }
                }
            }
        }
    }
    return false;
}

export function mapSatisfied(p, s, bo, mt) {
    if (s[bo + 1] === 0) {
        return false;
    }
    for (let f = 0; f < p[mt]; f++) {
        if (!factorSat(p, s, bo, mt, f)) {
            return false;
        }
    }
    return true;
}

export function mapMissing(p, s, bo, mt, d, pos) {
    // Witness rule 4 for this (alive, unsatisfied) block: its first factor
    // with no satisfied alternative, that factor's lowest-index live
    // alternative, its first unmet entry -- literal entries in source order,
    // then constrained group entries in priority order (§17 Q3); 1 unit per
    // entry examined. 0 or a negated code.
    const pools = mPools(p, mt);
    const alts = mAlts(p, mt);
    const lits = mLits(p, mt);
    for (let f = 0; f < p[mt]; f++) {
        if (!factorSat(p, s, bo, mt, f)) {
            const frec = (mt + 8) + (4 * f);
            const pf = p[frec + 2];
            const pc = p[frec + 3];
            for (let k = 0; k < pc; k++) {
                const prec = pools + (5 * (pf + k));
                const pso = p[prec + 4];
                const af = p[prec + 2];
                const ac = p[prec + 3];
                for (let ai = 0; ai < ac; ai++) {
                    const a = af + ai;
                    const arec = alts + (5 * a);
                    const aso = p[arec + 4];
                    const lf = p[arec + 1];
                    const lc = p[arec + 2];
                    if (altLive(p, s, bo, pools, alts, a)) {
                        for (let li = 0; li < lc; li++) {
                            if (!charge(s, 1, pos)) {
                                return -R_BUDGET;
                            }
                            const lrec = lits + (4 * (lf + li));
                            const word = s[((bo + aso) + 3) + (li >> 5)];
                            if ((p[lrec + 2] === 1) && ((word & (1 << (li & 31))) === 0)) {
                                witSet(s, R_MISSING, 0, d, P_KEY, p[lrec], pos);
                                return 0;
                            }
                        }
                        const g = p[prec + 1];
                        if (g >= 0) {
                            const go = groupRec(p, g);
                            const ne = p[go];
                            for (let j = 0; j < ne; j++) {
                                if (!charge(s, 1, pos)) {
                                    return -R_BUDGET;
                                }
                                const erec = (go + 2) + (4 * j);
                                const emin = p[erec + 2];
                                if ((!absorbing(emin, p[erec + 3])) && (s[((bo + pso) + 4) + j] < emin)) {
                                    witSet(s, R_MISSING, 0, d, P_ANYKEY, 0, pos);
                                    return 0;
                                }
                            }
                        }
                        witSet(s, R_MISSING, 0, d, -1, 0, pos);
                        return 0;
                    }
                }
            }
        }
    }
    witSet(s, R_MISSING, 0, d, -1, 0, pos);
    return 0;
}

export function keyProbe(p, pool, b, s, ks, ke, lo0) {
    // key-search without charging (P3.6 streaks): the id or -1; the next
    // lower bound in s[O_HI] and the units key-search would charge in
    // s[O_LO].
    const kb = p[H_S_KEYS];
    const kl = ke - ks;
    let lo = lo0;
    let hi = p[H_N_KEYS];
    let units = 0;
    if (lo > hi) {
        lo = hi;
    }
    while (lo < hi) {
        const mid = (lo + hi) >> 1;
        const ko = p[kb + (2 * mid)];
        const kn = p[(kb + (2 * mid)) + 1];
        units += c64min(kl, kn);
        const c = cmpBytes(b, ks, kl, pool, ko, kn);
        if (c === 0) {
            s[O_HI] = mid + 1;
            s[O_LO] = units;
            return mid;
        }
        if (c < 0) {
            hi = mid;
        } else {
            lo = mid + 1;
        }
    }
    s[O_HI] = lo;
    s[O_LO] = units;
    return -1;
}
